const {chromium}=require('playwright'),assert=require('node:assert/strict'),path=require('node:path'),fs=require('node:fs');
const hook=`window.discoveryTest={clock:0,now:0,cues:[],cancelled:[],target:null,
setup(){resumeGameV76();SkyAudio.rhythm=()=>({ready:true,epoch:123,beatIndex:Math.floor(this.clock),phase:this.clock%1,beatMs:60000/72});SkyAudio.discoveryCue=(beat,seed)=>{this.cues.push({beat,seed});return this.cues.length};SkyAudio.cancelDiscoveryCue=id=>this.cancelled.push(id);inspectLensTargetV79=()=>this.target;__buttonwood.render(performance.now());},
targetAt(title='Dirt',id='block:1'){this.target={key:id,title,text:title==='Water'?'A splash of something lovely.':'A tiny garden waiting to happen.',point:()=>({x:0,y:0})};inspectPointerV79={x:600,y:400,inside:true};inspectScanV79=-Infinity;},
advance(beat){this.now+=(beat-this.clock)*60000/72;this.clock=beat;inspectScanV79=-Infinity;pulseInspectV79(this.now)},
leave(){inspectPointerV79.inside=false;pulseInspectV79(this.now)},save(){saveGame();return JSON.parse(localStorage.getItem(SAVE_KEY))},restore(s){restoreDynamicState(s)},
state(){return {catalog:skyStackDiscoveries.state,title:discoveryBodyV90.querySelector('strong').textContent,label:discoveryLabelV90.textContent,mask:!discoveryMaskV90.hidden,bubble:!bubbleV79.hidden,cues:this.cues,cancelled:this.cancelled}}};`;
(async()=>{const b=await chromium.launch({headless:true,executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome'});try{const p=await b.newPage({viewport:{width:1280,height:900}}),errors=[];p.on('pageerror',e=>errors.push(e.message));await p.addInitScript(()=>requestAnimationFrame=()=>0);await p.route('**/game-v90-discoveries.txt*',async r=>{const response=await r.fetch();await r.fulfill({response,body:await response.text()+'\n'+hook})});await p.goto(process.env.SKY_TEST_URL||'http://127.0.0.1:8766/tower-of-babel/');await p.waitForFunction(()=>window.discoveryTest&&window.__buttonwood,null,{polling:100});await p.evaluate(()=>{discoveryTest.setup();skyStackInspect.setEnabled(true);discoveryTest.targetAt();discoveryTest.advance(0)});let s=await p.evaluate(()=>discoveryTest.state());assert.equal(s.catalog.count,0);assert(!s.bubble);
await p.evaluate(()=>discoveryTest.advance(2));s=await p.evaluate(()=>discoveryTest.state());assert.equal(s.title,'???');assert.equal(s.catalog.current.phase,'unknown');assert.equal(s.cues.length,0);
await p.evaluate(()=>discoveryTest.advance(4));s=await p.evaluate(()=>discoveryTest.state());assert(s.mask);assert.equal(s.catalog.count,0);assert.equal(s.cues[0].beat,6);
await p.evaluate(()=>discoveryTest.advance(5));const qa=path.join(__dirname,'../buttonwood/qa/discoveries');fs.mkdirSync(qa,{recursive:true});await p.screenshot({path:path.join(qa,'reveal.png')});await p.evaluate(()=>discoveryTest.advance(6));s=await p.evaluate(()=>discoveryTest.state());assert.equal(s.catalog.count,1);assert.equal(s.label,'New discovery');assert(!s.mask);assert.equal(s.catalog.rewards,1);await p.screenshot({path:path.join(qa,'discovered.png')});
const saved=await p.evaluate(()=>discoveryTest.save());assert.equal(saved.structuresV46.discoveriesV90.length,1);await p.evaluate(()=>{discoveryTest.leave();discoveryTest.targetAt('Dirt','block:999');discoveryTest.advance(8)});s=await p.evaluate(()=>discoveryTest.state());assert(s.catalog.current.known);assert.equal(s.title,'Dirt');assert.equal(s.cues.length,1);
await p.evaluate(()=>{discoveryTest.leave();discoveryTest.targetAt('Stone','block:2');discoveryTest.advance(10);discoveryTest.advance(12);discoveryTest.leave();discoveryTest.advance(14)});s=await p.evaluate(()=>discoveryTest.state());assert.equal(s.catalog.count,1);assert(s.cancelled.includes(2));assert(!s.bubble);
await p.evaluate(s=>discoveryTest.restore(s),saved);assert.equal((await p.evaluate(()=>discoveryTest.state())).catalog.count,1);
await p.setViewportSize({width:390,height:844});await p.waitForFunction(()=>document.querySelector('#game').style.width==='390px',null,{polling:100});await p.emulateMedia({reducedMotion:'reduce'});await p.evaluate(()=>{skyStackInspect.setEnabled(true);discoveryTest.targetAt('Water','liquid:water:1');inspectPointerV79={x:180,y:430,inside:true};discoveryTest.advance(16);discoveryTest.advance(18)});assert((await p.evaluate(()=>discoveryTest.state())).mask);await p.evaluate(()=>discoveryTest.advance(20));assert.equal((await p.evaluate(()=>discoveryTest.state())).catalog.count,2);await p.evaluate(()=>__buttonwood.render(performance.now()));const rect=await p.locator('#inspectBubbleV79').boundingBox();assert(rect.x>=8&&rect.x+rect.width<=382,JSON.stringify(rect));await p.screenshot({path:path.join(qa,'phone.png')});assert.deepEqual(errors,[]);console.log('PASS half-note mystery/reveal/reward, type deduplication, cancellation, per-world save/restore, reduced motion and phone layout');}finally{await b.close()}})().catch(e=>{console.error(e);process.exit(1)});
